/* C99/C11 Interleaving Declarations */

void process_data(int limit) {
    int sum = 0;

    for (int i = 0; i < limit; i++) {
        sum += i;
    }

    /* Declaration after statement block */
    if (sum > 100) {
        /* Local variable 'avg' declared mid-block */
        float avg = (float)sum / limit;
        printf("Average: %.2f\n", avg);
    }

    int result = sum * 2;
}

